export function getProgramName(argv) {
  const scriptPath = argv[1] ?? 'test6.mjs';
  const parts = scriptPath.split(/[\\/]/);
  return parts[parts.length - 1] || 'test6.mjs';
}

export function getUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

export function getHelp(programName) {
  return `${getUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B`;
}

export function formatError(programName, message) {
  return `${getUsage(programName)}\n${programName}: error: ${message}`;
}

export class CliParseError extends Error {
  constructor(message) {
    super(message);
    this.name = 'CliParseError';
  }
}

export function parseCommandLine(argv, parseInteger) {
  const tokens = argv.slice(2);
  let hasA = false;
  let hasB = false;
  let aValue = '';
  let bValue = 0n;
  const extras = [];

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '-h' || token === '--help') {
      return {
        kind: 'help',
      };
    }

    if (token === '--') {
      extras.push(...tokens.slice(index));
      break;
    }

    if (token === '--a') {
      const nextToken = tokens[index + 1];

      if (nextToken === undefined || isMissingOptionArgument(nextToken)) {
        throw new CliParseError('argument --a: expected one argument');
      }

      hasA = true;
      aValue = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      hasA = true;
      aValue = token.slice(4);
      continue;
    }

    if (token === '--b') {
      const nextToken = tokens[index + 1];

      if (nextToken === undefined || isMissingOptionArgument(nextToken)) {
        throw new CliParseError('argument --b: expected one argument');
      }

      hasB = true;
      bValue = parseInteger(nextToken);
      index += 1;
      continue;
    }

    if (token.startsWith('--b=')) {
      hasB = true;
      bValue = parseInteger(token.slice(4));
      continue;
    }

    extras.push(token);
  }

  const missing = [];

  if (!hasA) {
    missing.push('--a');
  }

  if (!hasB) {
    missing.push('--b');
  }

  if (missing.length > 0) {
    throw new CliParseError(`the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    throw new CliParseError(`unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    kind: 'run',
    values: {
      a: aValue,
      b: bValue,
    },
  };
}

function isMissingOptionArgument(token) {
  if (token === '--') {
    return true;
  }

  if (token === '-') {
    return false;
  }

  if (token.startsWith('--')) {
    return true;
  }

  if (token.startsWith('-') && !/^-([0-9](?:_?[0-9])*)$/.test(token)) {
    return true;
  }

  return false;
}

