function findFirstNonAscii(text) {
  let position = 0;

  for (const character of text) {
    const codePoint = character.codePointAt(0);

    if (codePoint > 0x7f) {
      return {
        character,
        codePoint,
        position,
      };
    }

    position += 1;
  }

  return null;
}

function formatAsciiCodecMessage(details) {
  return `UnicodeEncodeError: 'ascii' codec can't encode character '${formatCodePoint(details.codePoint)}' in position ${details.position}: ordinal not in range(128)`;
}

function formatCodePoint(codePoint) {
  if (codePoint <= 0xff) {
    return `\\x${toHex(codePoint, 2)}`;
  }

  if (codePoint <= 0xffff) {
    return `\\u${toHex(codePoint, 4)}`;
  }

  return `\\U${toHex(codePoint, 8)}`;
}

function toHex(value, width) {
  return value.toString(16).padStart(width, '0');
}

