export function toPythonRepr(value) {
  if (value instanceof PyBytes) {
    return bytesRepr(value);
  }

  if (typeof value === 'bigint') {
    return value.toString();
  }

  if (typeof value === 'number') {
    return Number.isInteger(value) ? String(value) : value.toString();
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => toPythonRepr(item)).join(', ')}]`;
  }

  if (typeof value === 'string') {
    return stringRepr(value);
  }

  if (value === null) {
    return 'None';
  }

  throw new TypeError(`Unsupported Python repr value: ${String(value)}`);
}

export function bytesRepr(value) {
  return `b'${escapeBytes(value.asciiText)}'`;
}

export function stringRepr(value) {
  return `'${escapeString(value)}'`;
}

function escapeBytes(text) {
  let output = '';

  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);

    if (code === 0x5c) {
      output += '\\\\';
    } else if (code === 0x27) {
      output += "\\'";
    } else if (code === 0x09) {
      output += '\\t';
    } else if (code === 0x0a) {
      output += '\\n';
    } else if (code === 0x0d) {
      output += '\\r';
    } else if (code >= 0x20 && code <= 0x7e) {
      output += text[index];
    } else {
      output += `\\x${code.toString(16).padStart(2, '0')}`;
    }
  }

  return output;
}

function escapeString(text) {
  let output = '';

  for (const character of text) {
    const codePoint = character.codePointAt(0);

    if (character === '\\') {
      output += '\\\\';
    } else if (character === '\'') {
      output += "\\'";
    } else if (character === '\t') {
      output += '\\t';
    } else if (character === '\n') {
      output += '\\n';
    } else if (character === '\r') {
      output += '\\r';
    } else if (codePoint >= 0x20 && codePoint !== 0x7f) {
      output += character;
    } else if (codePoint <= 0xff) {
      output += `\\x${codePoint.toString(16).padStart(2, '0')}`;
    } else if (codePoint <= 0xffff) {
      output += `\\u${codePoint.toString(16).padStart(4, '0')}`;
    } else {
      output += `\\U${codePoint.toString(16).padStart(8, '0')}`;
    }
  }

  return output;
}

