function encodeValue(value) {
  if (value instanceof PyBytes) {
    return `${value.asciiText.length}:${value.asciiText}`;
  }

  if (typeof value === 'string') {
    return encodeValue(encodeAscii(value));
  }

  if (typeof value === 'bigint') {
    return `i${value.toString()}e`;
  }

  if (typeof value === 'number' && Number.isInteger(value)) {
    return `i${String(value)}e`;
  }

  if (Array.isArray(value)) {
    return `l${value.map((item) => encodeValue(item)).join('')}e`;
  }

  throw new TypeError(`Unsupported bencode value: ${String(value)}`);
}

